(7352594, 1150429, 16148, '<td valign="top">Terrific shot!  Very enjoyable image within an image.</td>', 'Terrific shot!  Very enjoyable image within an image.', '2015-05-22 21:53:24.000000', NULL, 1),
(7352597, 1150110, 16148, '<td valign="top">Beautiful art nude!  I hope this scores well for you.</td>', 'Beautiful art nude!  I hope this scores well for you.', '2015-05-22 22:09:09.000000', NULL, 1),
(7352598, 1150383, 16148, '<td valign="top">The scratches enhance the motion blur and add interest.  Nice collection of shapes and patterns.</td>', 'The scratches enhance the motion blur and add interest.  Nice collection of shapes and patterns.', '2015-05-22 22:11:49.000000', NULL, 1),
(7352611, 1150225, 30982, '<td valign="top">I''m guessing the light leaks are post?  I''d prefer just one "beam" of light to simlate the moon''s light.  Two seems kinda confusing.</td>', 'I''m guessing the light leaks are post?  I''d prefer just one "beam" of light to simlate the moon''s light.  Two seems kinda confusing.', '2015-05-22 23:53:52.000000', NULL, 1),
(7352612, 1150197, 30982, '<td valign="top">Heh!  Nice use of light leak!  Good base picture to start with and the color adds a bit of fun.</td>', 'Heh!  Nice use of light leak!  Good base picture to start with and the color adds a bit of fun.', '2015-05-22 23:54:27.000000', NULL, 1),
(7352613, 1150424, 30982, '<td valign="top">Very old school - nice old paper, good lighting, and the pearls are a nice touch.</td>', 'Very old school - nice old paper, good lighting, and the pearls are a nice touch.', '2015-05-22 23:54:53.000000', NULL, 1),
(7352614, 1150179, 30982, '<td valign="top">Old school, but just a tad claustrophobic for such an open scene.</td>', 'Old school, but just a tad claustrophobic for such an open scene.', '2015-05-22 23:56:57.000000', NULL, 1),
(7352615, 1150106, 30982, '<td valign="top">The overlay doesn''t seem to be as well integrated here as in shoom.  More like the picture got wet somewhere along the line - made it through a flood perhaps.</td>', 'The overlay doesn''t seem to be as well integrated here as in shoom.  More like the picture got wet somewhere along the line - made it through a flood perhaps.', '2015-05-22 23:57:37.000000', NULL, 1),
(7352616, 1150006, 30982, '<td valign="top">What a great subject - totally fits your processing!</td>', 'What a great subject - totally fits your processing!', '2015-05-22 23:57:58.000000', NULL, 1),
