(7352624, 1149982, 30982, '<td valign="top">Good late night lights.</td>', 'Good late night lights.', '2015-05-23 00:35:50.000000', NULL, 1),
(7352625, 1150461, 30982, '<td valign="top">I love bleach bypass.  Nice light treatment of it here.  Lovely photo, too!</td>', 'I love bleach bypass.  Nice light treatment of it here.  Lovely photo, too!', '2015-05-23 00:36:20.000000', NULL, 1),
(7352626, 1150468, 30982, '<td valign="top">Good old school film colors.  Pretty girls!!</td>', 'Good old school film colors.  Pretty girls!!', '2015-05-23 00:36:40.000000', NULL, 1),
(7352627, 1150421, 30982, '<td valign="top">Interesting dichotomy of the "old school" filmic application with the very new school selfie stick.</td>', 'Interesting dichotomy of the "old school" filmic application with the very new school selfie stick.', '2015-05-23 00:37:14.000000', NULL, 1),
(7352628, 1150227, 30982, '<td valign="top">An odd sort of picture to choose for the challenge - one might almost expect him to be chopping wood with an ax instead!  I like the scratches.</td>', 'An odd sort of picture to choose for the challenge - one might almost expect him to be chopping wood with an ax instead!  I like the scratches.', '2015-05-23 00:38:01.000000', NULL, 1),
(7352629, 1150358, 30982, '<td valign="top">Nice lighting on the chin hairs and really nice bokeh.</td>', 'Nice lighting on the chin hairs and really nice bokeh.', '2015-05-23 00:38:26.000000', NULL, 1),
(7352630, 1150435, 30982, '<td valign="top">Good application of the post processing film setting; kind of a bland subject to me - wonder if it works better in color?</td>', 'Good application of the post processing film setting; kind of a bland subject to me - wonder if it works better in color?', '2015-05-23 00:39:24.000000', NULL, 1),
(7352631, 1150470, 30982, '<td valign="top">Ha!  Amusing subject matter.  Nice "faded" look to go along with the history aspect.</td>', 'Ha!  Amusing subject matter.  Nice "faded" look to go along with the history aspect.', '2015-05-23 00:39:54.000000', NULL, 1),
(7352632, 1150457, 30982, '<td valign="top">That''s a cushion on a couch?  How bizarre!  (Use the full real estate when presenting pictures here - you can have this be 1200 pixels wide.)</td>', 'That''s a cushion on a couch?  How bizarre!  (Use the full real estate when presenting pictures here - you can have this be 1200 pixels wide.)', '2015-05-23 00:40:28.000000', NULL, 1),
