(7352717, 1150458, 30982, '<td valign="top">Filmic effects work well with this one.</td>', 'Filmic effects work well with this one.', '2015-05-24 01:28:38.000000', NULL, 1),
(7352718, 1150110, 30982, '<td valign="top">A wet plate kinda thing - works well here.</td>', 'A wet plate kinda thing - works well here.', '2015-05-24 01:28:57.000000', NULL, 1),
