(7352724, 1150455, 30982, '<td valign="top">The filmic treatment here (light leak?) doesn''t seem to "fit" the photo very well.  Wondering if for the challenge if a grainly B&amp;W or perhaps just a faded color would have worked a bit better.</td>', 'The filmic treatment here (light leak?) doesn''t seem to "fit" the photo very well.  Wondering if for the challenge if a grainly B&W or perhaps just a faded color would have worked a bit better.', '2015-05-24 01:32:02.000000', NULL, 1),
(7352725, 1150091, 30982, '<td valign="top">Does have a retro feel - also seems a bit unsettled.</td>', 'Does have a retro feel - also seems a bit unsettled.', '2015-05-24 01:33:51.000000', NULL, 1),
(7352726, 1150377, 30982, '<td valign="top">Bird in a bike basket?  Harsh light beyond tends to pull the eye away from the bird a bit.</td>', 'Bird in a bike basket?  Harsh light beyond tends to pull the eye away from the bird a bit.', '2015-05-24 01:34:21.000000', NULL, 1),
(7352727, 1150401, 30982, '<td valign="top">It does look a little green/blue.  Subject matter is just a bit bland as presented - perhaps a more dramatic angle?</td>', 'It does look a little green/blue.  Subject matter is just a bit bland as presented - perhaps a more dramatic angle?', '2015-05-24 01:35:00.000000', NULL, 1),
(7352728, 1150355, 30982, '<td valign="top">Looks nicely preserved!</td>', 'Looks nicely preserved!', '2015-05-24 01:35:15.000000', NULL, 1),
