(7352731, 1150261, 30982, '<td valign="top">Oh my goodness - unreal!  Overdone on the vignetting perhaps, but great subject matter.</td>', 'Oh my goodness - unreal!  Overdone on the vignetting perhaps, but great subject matter.', '2015-05-24 01:37:19.000000', NULL, 1),
(7352733, 1149942, 30982, '<td valign="top">The light leak effect in the middle seems unrealistic to me - the "leak" on the left side is more natural, if that makes sense.  Love the birds, though!</td>', 'The light leak effect in the middle seems unrealistic to me - the "leak" on the left side is more natural, if that makes sense.  Love the birds, though!', '2015-05-24 01:38:22.000000', NULL, 1),
