(7352735, 1150342, 30982, '<td valign="top">Nice old school feel.</td>', 'Nice old school feel.', '2015-05-24 01:39:10.000000', NULL, 1),
(7352754, 1150456, 30982, '<td valign="top">For some reason, I think of blur as a digital byproduct but it surely existed in film as well.  I''m sure I have actual burry analog prints somewhere... Or did at one time.  I like that he has is very own continent here.</td>', 'For some reason, I think of blur as a digital byproduct but it surely existed in film as well.  I''m sure I have actual burry analog prints somewhere... Or did at one time.  I like that he has is very own continent here.', '2015-05-24 13:00:53.000000', NULL, 1),
(7352755, 1150259, 30982, '<td valign="top">Nicely grained, so much to see!</td>', 'Nicely grained, so much to see!', '2015-05-24 13:01:12.000000', NULL, 1),
(7352756, 1150100, 30982, '<td valign="top">Classic composition and the light leaking in from above suits this well.</td>', 'Classic composition and the light leaking in from above suits this well.', '2015-05-24 13:04:14.000000', NULL, 1),
(7352757, 1150352, 30982, '<td valign="top">Nice find out int he middle of nowhere.</td>', 'Nice find out int he middle of nowhere.', '2015-05-24 13:04:31.000000', NULL, 1),
