(7354499, 1150050, 16106, '<td valign="top">Shades of Gerhard Richter, cold light and warm colors. Im sure many will hate the chair but for me it makes the image.</td>', 'Shades of Gerhard Richter, cold light and warm colors. Im sure many will hate the chair but for me it makes the image.', '2015-05-28 06:05:14.000000', NULL, 1),
(7354500, 1150110, 61396, '<td valign="top">always beautiful (and a nice reference to the early 20th century baby pictures)</td>', 'always beautiful (and a nice reference to the early 20th century baby pictures)', '2015-05-28 06:06:47.000000', NULL, 1),
(7354516, 1150384, 156466, '<td valign="top">Love this captured moment.</td>', 'Love this captured moment.', '2015-05-28 08:58:29.000000', NULL, 1),
(7354517, 1150455, 156466, '<td valign="top">Not a fan of the light leak for light leak''s sake - at least that''s how it feels.  Otherwise I like the photo and "filmic" treatment a lot.</td>', 'Not a fan of the light leak for light leak''s sake - at least that''s how it feels.  Otherwise I like the photo and "filmic" treatment a lot.', '2015-05-28 09:00:11.000000', NULL, 1),
(7354518, 1150433, 156466, '<td valign="top">Would like a little more room on the left.  Nice B&amp;W street shot but I''m missing a film feel here.</td>', 'Would like a little more room on the left.  Nice B&W street shot but I''m missing a film feel here.', '2015-05-28 09:01:52.000000', NULL, 1),
(7354519, 1150290, 156466, '<td valign="top">The title saved you on this.  I think we''ve become so used to filmic processing on modern work that we forget its origins and I almost did.</td>', 'The title saved you on this.  I think we''ve become so used to filmic processing on modern work that we forget its origins and I almost did.', '2015-05-28 09:04:17.000000', NULL, 1),
(7354520, 1150457, 156466, '<td valign="top">Curious as to why you uploaded it so small?</td>', 'Curious as to why you uploaded it so small?', '2015-05-28 09:04:44.000000', NULL, 1),
(7354521, 1149940, 156466, '<td valign="top">Not digging the modern look of the buildings with the filmic look.  This particular juxtaposition doesn''t work for me.</td>', 'Not digging the modern look of the buildings with the filmic look.  This particular juxtaposition doesn''t work for me.', '2015-05-28 09:06:30.000000', NULL, 1),
(7354522, 1150447, 156466, '<td valign="top">I think I would have preferred a lovely Kodachrome 64 look here.  Or at least less grain to a faded slide.</td>', 'I think I would have preferred a lovely Kodachrome 64 look here.  Or at least less grain to a faded slide.', '2015-05-28 09:08:09.000000', NULL, 1),
(7354528, 1150110, 156466, '<td valign="top">I''ve got to wonder if the wet plate look, if added in post and not on the original, might have nudged this over the edge for Advanced.  Leaks were allowed, but I''m thinking the textures may be over the top here.  Voting as if they''re not, but a DQ wouldn''t surprise me.</td>', 'I''ve got to wonder if the wet plate look, if added in post and not on the original, might have nudged this over the edge for Advanced.  Leaks were allowed, but I''m thinking the textures may be over the top here.  Voting as if they''re not, but a DQ wouldn''t surprise me.', '2015-05-28 09:11:59.000000', NULL, 1),
(7354529, 1150367, 156466, '<td valign="top">Center feels a touch too sharp for the look.</td>', 'Center feels a touch too sharp for the look.', '2015-05-28 09:12:36.000000', NULL, 1),
(7354530, 1150469, 156466, '<td valign="top">Feels like there''s too much wasted space at the top.</td>', 'Feels like there''s too much wasted space at the top.', '2015-05-28 09:13:51.000000', NULL, 1),
(7354532, 1150422, 156466, '<td valign="top">A little heavy on the glow, I think.</td>', 'A little heavy on the glow, I think.', '2015-05-28 09:15:17.000000', NULL, 1),
(7354533, 1150138, 156466, '<td valign="top">Juxtaposition of everything modern with the treatment doesn''t work for me.</td>', 'Juxtaposition of everything modern with the treatment doesn''t work for me.', '2015-05-28 09:16:14.000000', NULL, 1),
(7354535, 1149942, 156466, '<td valign="top">I like the leak, but might like it more backed off a touch.</td>', 'I like the leak, but might like it more backed off a touch.', '2015-05-28 09:17:34.000000', NULL, 1),
(7354536, 1150361, 156466, '<td valign="top">Needed to back off on the contrast for a better faded look.</td>', 'Needed to back off on the contrast for a better faded look.', '2015-05-28 09:18:45.000000', NULL, 1),
(7354537, 1150463, 156466, '<td valign="top">Not sure I''m getting the title, even if it does try and tie in with "Millennial"</td>', 'Not sure I''m getting the title, even if it does try and tie in with "Millennial"', '2015-05-28 09:20:11.000000', NULL, 1),
(7354539, 1150421, 156466, '<td valign="top">I''ve complained about the juxtaposition of modern and old filmic looks on other shots.  Not here - this one works for me.</td>', 'I''ve complained about the juxtaposition of modern and old filmic looks on other shots.  Not here - this one works for me.', '2015-05-28 09:21:46.000000', NULL, 1),
(7354540, 1150225, 156466, '<td valign="top">Nice shot, but this just screams digital darkroom and not film to me.</td>', 'Nice shot, but this just screams digital darkroom and not film to me.', '2015-05-28 09:22:22.000000', NULL, 1),
(7354541, 1150428, 156466, '<td valign="top">Wish it didn''t have the modern wrecker in the background.</td>', 'Wish it didn''t have the modern wrecker in the background.', '2015-05-28 09:23:05.000000', NULL, 1),
(7354542, 1150352, 156466, '<td valign="top">If only the pumps were still there.</td>', 'If only the pumps were still there.', '2015-05-28 09:23:50.000000', NULL, 1),
(7354543, 1150452, 156466, '<td valign="top">Being better behaved in this one, I see. ;)</td>', 'Being better behaved in this one, I see. ;)', '2015-05-28 09:24:24.000000', NULL, 1),
(7354565, 1150290, 97225, '<td valign="top">Awesome clouds!</td>', 'Awesome clouds!', '2015-05-28 09:42:01.000000', NULL, 1),
(7354566, 1150428, 97225, '<td valign="top">Retro look of the processing goes extremely well with the old car.</td>', 'Retro look of the processing goes extremely well with the old car.', '2015-05-28 09:43:04.000000', NULL, 1),
(7354569, 1150344, 97225, '<td valign="top">My favourite in this challenge. Love the happy vibe and the retro look.</td>', 'My favourite in this challenge. Love the happy vibe and the retro look.', '2015-05-28 09:44:47.000000', NULL, 1),
