INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7357149, 1150224, 115814, '<td valign="top">Hey Ronnie - Greetings from the Critique Club...<br/> <br/>A powerful image, for sure. I scored it with a 7. <br/> <br/>What caught my eye in a good way was the immediate impact of the high contrast processing and the intensity of the eyes. It''s well-composed and for me, has the right amount of breathing room between the subject and the edges. <br/> <br/>What caught my eye in a "hmm... I wonder" way was the combination of grittiness of the high contrast and grain. On first glance I see a sharp, well  defined image... as I look more closely, I wonder about what pulling back a bit on sharpening and/or contrast might do.<br/> <br/>What caught my eye in a "wish it were different" way is the background. Although the subject is isolated to some degree by the shallow DOF, it remains rather busy and competes with the subject for my attention. the grain is more apparent in the background, too which adds to the distraction. Finally, the dark area (a tree trunk?) in the top right draws attention away from the face, and I can''t help but see an old woman''s skirt and boney hand in the form. <br/> <br/>So... take it FWIW. I hope my comments are helpful. The bottom line is this is a terrific image with LOTS of great stuff going on. <br/> <br/>- Bill <br/> <br/></td>', 'Hey Ronnie - Greetings from the Critique Club... A powerful image, for sure. I scored it with a 7.  What caught my eye in a good way was the immediate impact of the high contrast processing and the intensity of the eyes. It''s well-composed and for me, has the right amount of breathing room between the subject and the edges.  What caught my eye in a "hmm... I wonder" way was the combination of grittiness of the high contrast and grain. On first glance I see a sharp, well  defined image... as I look more closely, I wonder about what pulling back a bit on sharpening and/or contrast might do. What caught my eye in a "wish it were different" way is the background. Although the subject is isolated to some degree by the shallow DOF, it remains rather busy and competes with the subject for my attention. the grain is more apparent in the background, too which adds to the distraction. Finally, the dark area (a tree trunk?) in the top right draws attention away from the face, and I can''t help but see an old woman''s skirt and boney hand in the form.  So... take it FWIW. I hope my comments are helpful. The bottom line is this is a terrific image with LOTS of great stuff going on.  - Bill  ', '2015-06-04 03:33:50.000000', NULL, 0),
(7357199, 1150367, 174999, '<td valign="top">Congrats!!!! Was expecting this to do well!!!</td>', 'Congrats!!!! Was expecting this to do well!!!', '2015-06-04 11:53:23.000000', NULL, 0),
(7357436, 1149940, 100393, '<td valign="top">I can''t believe this took the Brown. I think it''s a very sophisticated image. I was a 7 but now wish I''d given more.</td>', 'I can''t believe this took the Brown. I think it''s a very sophisticated image. I was a 7 but now wish I''d given more.', '2015-06-05 03:04:41.000000', NULL, 0),
(7377937, 1150179, 46918, '<td valign="top">Hello from the critique club...<br/> <br/>Stunning image.... I liked it very much. I absolutely love the clouds. Even though the image is a bit dark there is still plenty of detail. I am also a fan of the rays from the sun. Good job. I definitely think this shot was under rated. Happy shooting</td>', 'Hello from the critique club... Stunning image.... I liked it very much. I absolutely love the clouds. Even though the image is a bit dark there is still plenty of detail. I am also a fan of the rays from the sun. Good job. I definitely think this shot was under rated. Happy shooting', '2015-06-30 18:11:12.000000', NULL, 0);
COMMIT;
